import numpy as np
import trimesh


def create_model(points):
    meshes = []

    for x, y, z, r in points:
        sphere = trimesh.creation.icosphere(
            subdivisions=2,
            radius=r
        )

        sphere.apply_translation([x, 255-y, z])
        meshes.append(sphere)

    # Combine all spheres into one mesh
    model = trimesh.util.concatenate(meshes)

    return model

